# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: Test-MerchantFlow.ps1

# ============================================================================
# CONFIGURATION
# ============================================================================
$API_GATEWAY   = "http://localhost:8080"
$FRAUD_SERVICE = "http://localhost:8004"
$SECRET_KEY    = "sk_test_123"

$pass = 0
$fail = 0

function Write-Header { param([string]$t)
    Write-Host "`n$("="*70)" -ForegroundColor Cyan
    Write-Host "  $t" -ForegroundColor Cyan
    Write-Host "$("="*70)" -ForegroundColor Cyan
}

function Write-Step { param([string]$t)
    Write-Host "`n► $t" -ForegroundColor Yellow
}

function Pass { param([string]$t)
    Write-Host "  ✓ $t" -ForegroundColor Green
    $script:pass++
}

function Fail { param([string]$t, [string]$e="")
    Write-Host "  ✗ $t" -ForegroundColor Red
    if ($e) { Write-Host "    $e" -ForegroundColor DarkRed }
    $script:fail++
}

function Info { param([string]$t)
    Write-Host "    $t" -ForegroundColor White
}

function New-IdempotencyKey { return "merch_$(Get-Date -Format 'yyyyMMddHHmmss')_$([System.Guid]::NewGuid().ToString('N').Substring(0,6))" }

$merchantHeaders = @{
    "Content-Type"  = "application/json"
    "Authorization" = "Bearer $SECRET_KEY"
}

Clear-Host
Write-Host "`n╔$("═"*68)╗" -ForegroundColor Cyan
Write-Host "║$(" "*20)MERCHANT FLOW - COMPLETE TEST$(" "*19)║" -ForegroundColor Cyan
Write-Host "╚$("═"*68)╝" -ForegroundColor Cyan

# ============================================================================
# TEST 1: HEALTH
# ============================================================================
Write-Header "TEST 1: HEALTH CHECK"

Write-Step "API Gateway health"
try {
    $h = Invoke-RestMethod -Uri "$API_GATEWAY/health" -Method GET
    if ($h.status -eq "ok") { Pass "API Gateway healthy" }
    else { Fail "Unhealthy" }
} catch { Fail "Unreachable" $_; exit 1 }

# ============================================================================
# TEST 2: AUTHORIZATION ONLY
# ============================================================================
Write-Header "TEST 2: CREATE PAYMENT - AUTHORIZATION ONLY (capture=false)"

Write-Step "Authorize $150 Visa payment"
try {
    $authHeaders = $merchantHeaders.Clone()
    $authHeaders["Idempotency-Key"] = New-IdempotencyKey

    $authPayment = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $authHeaders `
        -Body (@{
            amount      = 15000
            currency    = "usd"
            customer    = @{ email="customer@example.com"; name="John Doe"; phone="+1234567890" }
            card        = @{ number="4242424242424242"; exp_month=12; exp_year=2026; cvc="123" }
            order_id    = "order_auth_$(Get-Date -Format 'yyyyMMddHHmmss')"
            description = "Authorization test - annual subscription"
            metadata    = @{ plan="enterprise"; seats=10; billing="annual" }
            capture     = $false
        } | ConvertTo-Json)

    $AUTH_PAYMENT_ID = $authPayment.payment_id
    if ($AUTH_PAYMENT_ID) {
        Pass "Payment authorized"
        Info "Payment ID: $AUTH_PAYMENT_ID"
        Info "Status: $($authPayment.status)"
        Info "Auth Code: $($authPayment.authorization_code)"
        Info "Amount: `$$($authPayment.amount/100)"
        Info "Card: $($authPayment.card_brand) **** $($authPayment.card_last4)"
    } else { Fail "No payment ID returned" }
} catch {
    Fail "Authorization failed" $_
    $e = $_.ErrorDetails.Message | ConvertFrom-Json
    Info "Error: $($e.detail)"
    exit 1
}

# ============================================================================
# TEST 3: RETRIEVE PAYMENT
# ============================================================================
Write-Header "TEST 3: RETRIEVE PAYMENT"

Write-Step "Get payment details"
try {
    $details = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/payments/$AUTH_PAYMENT_ID" `
        -Method GET -Headers $merchantHeaders

    if ($details.payment_id -eq $AUTH_PAYMENT_ID) {
        Pass "Payment retrieved"
        Info "Status: $($details.status)"
        Info "Amount: `$$($details.amount/100)"
        Info "Captured: `$$($details.amount_captured/100)"
        Info "Refunded: `$$($details.amount_refunded/100)"
        Info "Order ID: $($details.order_id)"
    } else { Fail "Wrong payment returned" }
} catch { Fail "Retrieval failed" $_ }

# ============================================================================
# TEST 4: FULL CAPTURE
# ============================================================================
Write-Header "TEST 4: FULL CAPTURE"

Write-Step "Capture full $150"
try {
    $capture = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/captures" `
        -Method POST -Headers $merchantHeaders `
        -Body (@{ payment_id=$AUTH_PAYMENT_ID; amount=$null } | ConvertTo-Json)

    if ($capture.status -eq "captured") {
        Pass "Full capture successful"
        Info "Status: $($capture.status)"
        Info "Captured: `$$($capture.captured_amount/100)"
        Info "Reference: $($capture.capture_reference)"
    } else { Fail "Unexpected status: $($capture.status)" }
} catch { Fail "Capture failed" $_ }

# ============================================================================
# TEST 5: PARTIAL REFUND
# ============================================================================
Write-Header "TEST 5: PARTIAL REFUND"

Write-Step "Refund $50 of $150"
try {
    $refund = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/refunds" `
        -Method POST -Headers $merchantHeaders `
        -Body (@{
            payment_id = $AUTH_PAYMENT_ID
            amount     = 5000
            reason     = "Customer returned 1 item"
            metadata   = @{ type="partial"; items_returned=@("item_001") }
        } | ConvertTo-Json)

    if ($refund.status -eq "succeeded") {
        Pass "Partial refund processed"
        Info "Refund ID: $($refund.id)"
        Info "Amount: `$$($refund.amount/100)"
        Info "Status: $($refund.status)"
    } else { Fail "Unexpected status: $($refund.status)" }
} catch { Fail "Partial refund failed" $_ }

# ============================================================================
# TEST 6: FULL REFUND (new payment)
# ============================================================================
Write-Header "TEST 6: FULL REFUND"

Write-Step "Create new payment for full refund test"
try {
    $h = $merchantHeaders.Clone()
    $h["Idempotency-Key"] = New-IdempotencyKey

    $refundPayment = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $h `
        -Body (@{
            amount   = 10000
            currency = "usd"
            customer = @{ email="refund@example.com"; name="Refund Test" }
            card     = @{ number="5555555555554444"; exp_month=12; exp_year=2026; cvc="123" }
            capture  = $true
        } | ConvertTo-Json)

    $REFUND_PAYMENT_ID = $refundPayment.payment_id
    Pass "Payment created: $REFUND_PAYMENT_ID"

    Start-Sleep -Seconds 2

    Write-Step "Process full refund"
    $fullRefund = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/refunds" `
        -Method POST -Headers $merchantHeaders `
        -Body (@{
            payment_id = $REFUND_PAYMENT_ID
            amount     = $null
            reason     = "Full cancellation - customer request"
        } | ConvertTo-Json)

    if ($fullRefund.status -eq "succeeded") {
        Pass "Full refund processed"
        Info "Refund ID: $($fullRefund.id)"
        Info "Amount: `$$($fullRefund.amount/100)"
    } else { Fail "Unexpected status: $($fullRefund.status)" }
} catch { Fail "Full refund test failed" $_ }

# ============================================================================
# TEST 7: PARTIAL CAPTURE
# ============================================================================
Write-Header "TEST 7: PARTIAL CAPTURE"

Write-Step "Authorize $100 then capture $60"
try {
    $h = $merchantHeaders.Clone()
    $h["Idempotency-Key"] = New-IdempotencyKey

    $partialAuth = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $h `
        -Body (@{
            amount   = 10000
            currency = "usd"
            customer = @{ email="partial@example.com"; name="Partial Test" }
            card     = @{ number="4242424242424242"; exp_month=12; exp_year=2026; cvc="123" }
            capture  = $false
        } | ConvertTo-Json)

    $PARTIAL_ID = $partialAuth.payment_id
    Pass "Payment authorized: $PARTIAL_ID"

    Start-Sleep -Seconds 1

    $partCapture = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/captures" `
        -Method POST -Headers $merchantHeaders `
        -Body (@{ payment_id=$PARTIAL_ID; amount=6000 } | ConvertTo-Json)

    if ($partCapture.status -eq "partially_captured") {
        Pass "Partial capture successful"
        Info "Captured: `$$($partCapture.captured_amount/100) of `$100.00"
    } else { Fail "Status: $($partCapture.status)" }
} catch { Fail "Partial capture failed" $_ }

# ============================================================================
# TEST 8: VOID
# ============================================================================
Write-Header "TEST 8: VOID AUTHORIZED PAYMENT"

Write-Step "Authorize then void"
try {
    $h = $merchantHeaders.Clone()
    $h["Idempotency-Key"] = New-IdempotencyKey

    $voidAuth = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $h `
        -Body (@{
            amount   = 8000
            currency = "usd"
            customer = @{ email="void@example.com"; name="Void Test" }
            card     = @{ number="5555555555554444"; exp_month=12; exp_year=2026; cvc="123" }
            capture  = $false
        } | ConvertTo-Json)

    $VOID_ID = $voidAuth.payment_id
    Pass "Payment authorized: $VOID_ID"

    Start-Sleep -Seconds 1

    $void = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/voids" `
        -Method POST -Headers $merchantHeaders `
        -Body (@{ payment_id=$VOID_ID; reason="Customer cancelled order" } | ConvertTo-Json)

    if ($void.status -eq "voided") {
        Pass "Payment voided"
        Info "Void Reference: $($void.void_reference)"
    } else { Fail "Status: $($void.status)" }
} catch { Fail "Void failed" $_ }

# ============================================================================
# TEST 9: IMMEDIATE CAPTURE
# ============================================================================
Write-Header "TEST 9: IMMEDIATE CAPTURE (capture=true)"

Write-Step "Create payment with auto-capture"
try {
    $h = $merchantHeaders.Clone()
    $h["Idempotency-Key"] = New-IdempotencyKey

    $immediate = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $h `
        -Body (@{
            amount   = 12000
            currency = "usd"
            customer = @{ email="auto@example.com"; name="Auto Capture" }
            card     = @{ number="4242424242424242"; exp_month=12; exp_year=2026; cvc="123" }
            capture  = $true
        } | ConvertTo-Json)

    Pass "Payment created with auto-capture"
    Info "Payment ID: $($immediate.payment_id)"
    Info "Status: $($immediate.status)"
    Info "Captured: `$$($immediate.amount_captured/100)"
} catch { Fail "Auto-capture failed" $_ }

# ============================================================================
# TEST 10: IDEMPOTENCY
# ============================================================================
Write-Header "TEST 10: IDEMPOTENCY"

Write-Step "Same request twice with same idempotency key"
try {
    $iKey = "idem_$(Get-Date -Format 'yyyyMMddHHmmss')"
    $iHeaders = $merchantHeaders.Clone()
    $iHeaders["Idempotency-Key"] = $iKey
    $iBody = @{
        amount=3000; currency="usd"
        customer=@{email="idem@example.com"; name="Idem Test"}
        card=@{number="5555555555554444"; exp_month=12; exp_year=2026; cvc="123"}
        capture=$false
    } | ConvertTo-Json

    $first = Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $iHeaders -Body $iBody
    Start-Sleep -Seconds 1
    $second = Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $iHeaders -Body $iBody

    if ($first.payment_id -eq $second.payment_id) {
        Pass "Idempotency working - same payment returned"
        Info "Payment ID: $($first.payment_id)"
    } else { Fail "Different payment IDs returned!" }
} catch { Fail "Idempotency test failed" $_ }

