Write-Header "TEST 11: ERROR HANDLING"

Write-Step "Invalid secret key"
try {
    Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/payments/pi_test" `
        -Method GET -Headers @{ "Authorization"="Bearer sk_invalid_999" }
    Fail "Should reject invalid key"
} catch {
    if ($_.Exception.Response.StatusCode.value__ -eq 401) { Pass "Invalid key rejected (401)" }
    else { Pass "Invalid key rejected" }
}

Write-Step "Capture already captured payment"
try {
    # Try to capture the already-captured AUTH payment
    Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/captures" `
        -Method POST -Headers $merchantHeaders `
        -Body (@{ payment_id=$AUTH_PAYMENT_ID } | ConvertTo-Json)
    Fail "Should reject already captured"
} catch { Pass "Double-capture rejected" }

Write-Step "Void already captured payment"
try {
    Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/voids" `
        -Method POST -Headers $merchantHeaders `
        -Body (@{ payment_id=$AUTH_PAYMENT_ID; reason="test" } | ConvertTo-Json)
    Fail "Should reject void of captured"
} catch { Pass "Void of captured rejected" }

Write-Step "Refund amount exceeds captured"
try {
    Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/refunds" `
        -Method POST -Headers $merchantHeaders `
        -Body (@{ payment_id=$AUTH_PAYMENT_ID; amount=999999 } | ConvertTo-Json)
    Fail "Should reject over-refund"
} catch { Pass "Over-refund rejected" }

Write-Step "Get non-existent payment"
try {
    Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/payments/pi_nonexistent_12345" `
        -Method GET -Headers $merchantHeaders
    Fail "Should reject non-existent"
} catch {
    if ($_.Exception.Response.StatusCode.value__ -eq 404) { Pass "Non-existent payment rejected (404)" }
    else { Pass "Non-existent payment rejected" }
}

